const suit=card=>Math.floor(card/13);
const rank=card=>card%13;
function legal(s){
  const hand=s.hands[s.seat];
  const follow=hand.filter(card=>s.trick.length&&suit(card)===suit(s.trick[0].card));
  return follow.length?follow:hand;
}
const game={
  newMatch(ctx){
    const deck=Array.from({length:52},(_,i)=>i);
    let seed=2166136261;
    for(const p of ctx.players)for(const c of p.id)seed=Math.imul(seed^c.charCodeAt(0),16777619);
    for(let i=51;i>0;i--){
      seed=(Math.imul(seed,1664525)+1013904223)>>>0;
      const j=seed%(i+1);[deck[i],deck[j]]=[deck[j],deck[i]];
    }
    return {state:{hands:ctx.players.map((_,i)=>deck.slice(13*i,13*i+13)),seat:0,trump:-1,trick:[],scores:[0,0],winners:[]},turn:[ctx.players[0].id]};
  },
  applyMove(s,id,m,ctx){
    const invalid=()=>{throw new InvalidMove("Choose a legal move on your turn.");};
    if(!m||Object.keys(m).length!==1||s.winners.length||ctx.players[s.seat].id!==id)invalid();
    if(s.trump<0){
      if(!Number.isInteger(m.trump)||m.trump<0||m.trump>3)invalid();
      return {state:{...s,trump:m.trump},turn:[id]};
    }
    if(!legal(s).includes(m.card))invalid();
    const hands=s.hands.map((hand,i)=>i===s.seat?hand.filter(c=>c!==m.card):hand);
    const next={...s,hands,trick:[...s.trick,{seat:s.seat,card:m.card}],seat:(s.seat+1)%4};
    if(next.trick.length===4){
      const lead=suit(next.trick[0].card);
      const strength=c=>rank(c)+(suit(c)===s.trump?26:suit(c)===lead?13:0);
      next.seat=next.trick.sort((a,b)=>strength(b.card)-strength(a.card))[0].seat;
      next.trick=[];
      next.scores=[...s.scores];
      const team=next.seat%2;
      if(++next.scores[team]===7)next.winners=[team,team+2];
    }
    if(!next.winners.length)return {state:next,turn:[ctx.players[next.seat].id]};
    const humans=ctx.players.filter(p=>p.kind==="human"&&p.active!==false);
    const winning=humans.filter(p=>next.winners.includes(ctx.players.indexOf(p)));
    const paid=winning.length?winning:humans;
    return {state:next,turn:null,payouts:Object.fromEntries(paid.map((p,i)=>[p.id,Math.floor(ctx.pot/paid.length)+(i<ctx.pot%paid.length?1:0)]))};
  },
  viewFor(s,id,ctx){
    const {hands,...visible}=s;
    const i=ctx.players.findIndex(p=>p.id===id), hand=hands[i]??[];
    return {...visible,hand:s.trump<0?(i===0?hand.slice(0,5):[]):hand,legal:i===s.seat&&s.trump>=0&&!s.winners.length?legal(s):[]};
  },
  computerMove(s){
    if(s.trump<0){
      const first=s.hands[0].slice(0,5);
      return {trump:[0,1,2,3].sort((a,b)=>first.filter(c=>suit(c)===b).length-first.filter(c=>suit(c)===a).length)[0]};
    }
    return {card:legal(s)[0]};
  },
  randomMove(s,id,ctx){
    if(s.trump<0)return {trump:Math.floor(ctx.random()*4)};
    const moves=legal(s);return {card:moves[Math.floor(ctx.random()*moves.length)]};
  }
};

